import { expect, test } from "../../fixtures";

test("listing vendors with limit 101 is rejected with 422", { tag: "@VEN-06" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");

  // Act
  const res = await member.get("/api/vendors?limit=101");

  // Assert
  expect(res.status(), await res.text()).toBe(422);
});
